package com.example.hms.utility;

import com.example.hms.model.User;

import java.security.SecureRandom;
import java.time.Duration;
import java.time.LocalDateTime;

/**
 * The one-time password an account is created with, or re-issued with at its first activation (QA r70 D3201):
 * 14 characters, at least one upper case letter, one lower case letter, one digit and one symbol, in a random
 * order.
 *
 * <p>Every password a person did not choose for themselves (generated by the server, or typed by an
 * administrator for someone else) is set through {@link #assign}: it is stored as a hash only, it must be changed
 * before the account can use the API ({@code forcePasswordChange}, enforced by
 * {@link com.example.hms.security.PasswordChangeGate}), and it stops working {@link #LIFETIME} after it was issued.
 * It is never e-mailed and never logged: the holder sees it once, on the activation page or from the registrar.
 * {@code TemporaryPasswordGuardTest} fails when a password is set anywhere else.
 */
public final class TemporaryPasswords {

    /** How long a temporary password works before the holder must ask for a reset link. */
    public static final Duration LIFETIME = Duration.ofHours(72);

    private static final SecureRandom SECURE_RANDOM = new SecureRandom();
    private static final String UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String LOWER = "abcdefghijklmnopqrstuvwxyz";
    private static final String DIGITS = "0123456789";
    private static final String SPECIAL = "!@#$%&*";
    private static final String ALL = UPPER + LOWER + DIGITS + SPECIAL;
    private static final int LENGTH = 14;

    private TemporaryPasswords() {
    }

    public static String generate() {
        // Guarantee one from each category
        StringBuilder sb = new StringBuilder(LENGTH);
        sb.append(UPPER.charAt(SECURE_RANDOM.nextInt(UPPER.length())));
        sb.append(LOWER.charAt(SECURE_RANDOM.nextInt(LOWER.length())));
        sb.append(DIGITS.charAt(SECURE_RANDOM.nextInt(DIGITS.length())));
        sb.append(SPECIAL.charAt(SECURE_RANDOM.nextInt(SPECIAL.length())));
        for (int i = 4; i < LENGTH; i++) {
            sb.append(ALL.charAt(SECURE_RANDOM.nextInt(ALL.length())));
        }
        // Shuffle to avoid predictable positions
        char[] chars = sb.toString().toCharArray();
        for (int i = chars.length - 1; i > 0; i--) {
            int j = SECURE_RANDOM.nextInt(i + 1);
            char tmp = chars[i];
            chars[i] = chars[j];
            chars[j] = tmp;
        }
        return new String(chars);
    }

    /**
     * Gives {@code user} a temporary password: its hash (never the password itself), the instant it was set, the
     * forced change, and the expiry.
     *
     * @param encodedHash the {@code PasswordEncoder} hash of the temporary password
     * @param issuedAt    when it was issued; it expires {@link #LIFETIME} later
     */
    public static void assign(User user, String encodedHash, LocalDateTime issuedAt) {
        user.setPasswordHash(encodedHash);
        user.setPasswordChangedAt(issuedAt);
        user.setForcePasswordChange(true);
        user.setTemporaryPasswordExpiresAt(issuedAt.plus(LIFETIME));
    }

    /** The holder has set a password of their own: nothing temporary is left to expire. */
    public static void retire(User user) {
        user.setTemporaryPasswordExpiresAt(null);
    }

    /** Whether the account's temporary password has expired at {@code now}; false for a password the holder chose. */
    public static boolean expired(LocalDateTime expiresAt, LocalDateTime now) {
        return expiresAt != null && !now.isBefore(expiresAt);
    }
}
